SELECT ?work ?workLabel ?lcsh WHERE {
  ?work wdt:P921 wd:Q17167 .
  ?work wdt:P244 ?lcsh .
  ?work wdt:P31/wdt:P279* wd:Q732577 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT ?site ?siteLabel ?pleiades WHERE {
  ?site wdt:P31/wdt:P279* wd:Q839954 .
  ?site wdt:P1584 ?pleiades .
  ?site wdt:P2348 ?period .
  ?period wdt:P31 wd:Q11514315 .
  FILTER(CONTAINS(STR(?period), "Q17167") || CONTAINS(STR(?period), "Roman"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT ?site ?siteLabel ?location WHERE {
  ?site wdt:P31/wdt:P279* wd:Q839954 .
  ?site wdt:P131 ?location .
  ?location wdt:P17 wd:Q38 .
  FILTER(CONTAINS(LCASE(STR(?siteLabel)), "roman"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language 'en' }
}

SELECT ?place ?placeLabel ?coords WHERE {
  VALUES ?place { wd:Q1139479 }
